// ── DCV: single reading, SI-formatted to match the DMM's own screen ────
// Plain scpi-commands shortcuts show the raw SCPI reply (scientific
// notation, e.g. "+1.234500E-03") with no formatting hook available --
// this needs to be a JS shortcut so the value can be SI-scaled first,
// same fmtVal() helper as LR v46 / the Acq family use.
function qts(r) {
    if (r===null||r===undefined) return "";
    if (typeof r==="string") return r;
    if (typeof r==="number") return String(r);
    if (r.data) {
        const t=new TextDecoder().decode(new Uint8Array(r.data));
        return t.charAt(0)==='#'?t.substring(2+parseInt(t.charAt(1))):t;
    }
    return String(r);
}

function fmtVal(v, sfx) {
    if (!isFinite(v)) return String(v) + " " + sfx;
    const a = Math.abs(v), sg = v < 0 ? "-" : "";
    const noP = sfx.indexOf("°") >= 0 || sfx === "";
    if (noP || a === 0) return sg + parseFloat(a.toPrecision(6)) + " " + sfx;
    const P = [[1e12,"T"],[1e9,"G"],[1e6,"M"],[1e3,"k"],[1,""],[1e-3,"m"],[1e-6,"μ"],[1e-9,"n"],[1e-12,"p"],[1e-15,"f"]];
    for (const [sc,px] of P) {
        if (a >= sc * 0.9999) {
            return sg + parseFloat((a/sc).toPrecision(6)) + " " + px + sfx;
        }
    }
    return sg + parseFloat(a.toPrecision(6)) + " " + sfx;
}

await connection.acquire(true);
try {
    connection.command("CONFigure:VOLTage:DC DEF,DEF");
    const raw = parseFloat(qts(await connection.query("READ?")).trim());
    if (!isFinite(raw)) throw new Error("No valid reading");
    notify.info("DCV: " + fmtVal(raw, "V"));
} catch(e) {
    notify.error("DCV failed: " + e.message);
} finally {
    connection.release();
}

