// ── 34465A Live Read v46 ──────────────────────────────────────────────────
// To stop: close this toast to reveal the Stop button in the Scripts panel.
// Uses READ? with IMMediate trigger — no interleaved SCPI queries
// during measurement. Range check done every RANGE_CHECK_EVERY readings by
// briefly querying CONFigure? BETWEEN readings (after READ? returns).
// ACV/ACI: two rows RMS + P-P. All others: single row.
//
const COUNT             = 2000;   // max readings (0 = unlimited)
const NPLC              = 1;      // DC/resistance only: 1=6.5 digits ~4 rdg/s  |  0.2=5.5 digits ~10 rdg/s
const AC_BANDWIDTH      = 200;    // AC bandwidth filter (Hz): 3=slow/accurate  20=medium  200=fast
const RANGE_CHECK_EVERY = 10;     // check for auto-range change every N readings

function qts(r) {
    if (r===null||r===undefined) return "";
    if (typeof r==="string") return r;
    if (typeof r==="number") return String(r);
    if (r.data) {
        const t = new TextDecoder().decode(new Uint8Array(r.data));
        return t.charAt(0)==='#' ? t.substring(2+parseInt(t.charAt(1))) : t;
    }
    return String(r);
}

const SI_P = [[1e12,"T"],[1e9,"G"],[1e6,"M"],[1e3,"k"],[1,""],[1e-3,"m"],[1e-6,"\u03bc"],[1e-9,"n"],[1e-12,"p"],[1e-15,"f"]];

function siFor(a) {
    if (a === 0) return {scale:1, pfx:""};
    for (const [s,p] of SI_P) { if (a >= s*0.9999) return {scale:s, pfx:p}; }
    return {scale:1e-15, pfx:"f"};
}

function fmt(v, scale) { return (v/scale).toFixed(4); }

function fmtVal(v, sfx) {
    if (!isFinite(v)) return String(v)+" "+sfx;
    const a=Math.abs(v), sg=v<0?"-":"";
    if (sfx.indexOf("\u00b0")>=0 || a===0) return sg+parseFloat(a.toPrecision(6))+" "+sfx;
    const {scale,pfx}=siFor(a);
    return sg+parseFloat((a/scale).toPrecision(6))+" "+pfx+sfx;
}

function parseConf(raw) {
    const s=raw.trim().replace(/"/g,""), p=s.split(/[\s,]+/);
    return {func:p[0]||s, range:parseFloat(p[1]), res:parseFloat(p[2])};
}

function buildHeader(func, range, res, sfx) {
    const r = (isFinite(range)&&range>0) ? "  "+fmtVal(range,sfx) : "";
    const d = (isFinite(res)  &&res  >0) ? "  res "+fmtVal(res,sfx) : "";
    return func+r+d;
}

function row3(label, sfx, a, b, c) {
    const ref=Math.abs(b)||Math.abs(a)||Math.abs(c)||1;
    const noP=sfx.indexOf("\u00b0")>=0;
    const {scale,pfx}=noP?{scale:1,pfx:""}:siFor(ref);
    const u=noP?sfx:pfx+sfx;
    const sep = label ? label+" "+u+": " : u+": ";
    return sep+fmt(a,scale)+" | "+fmt(b,scale)+" | "+fmt(c,scale);
}

const toastId = notify.info("34465A Live Read: starting...", {autoClose:false});


// ── Force a clean connection before any acquire ────────────────────────
// Disconnect and reconnect to clear any stuck acquire queue.
// Then acquire(true) to set up query response handling.
async function resetAndAcquire() {
    // Release any held lock without disconnecting.
    // Disconnect/reconnect caused READ? timeout — instrument not ready post-reconnect.
    try { connection.release(); } catch(e) {}
    await new Promise(r=>setTimeout(r,500));
    await connection.acquire(true);
}

await resetAndAcquire();

try {
    // ── Clear any prior errors and query initial state ─────────────────────
    connection.command("*CLS");
    await new Promise(r=>setTimeout(r,200));  // let *CLS settle

    let conf = parseConf(qts(await connection.query("CONFigure?")));
    const fUp = conf.func.toUpperCase();

    let sfx="", eezUnit="unknown", rangeQuery=null, nplcCmd=null, isAC=false, confCmd=null;
    if      (fUp.includes("VOLT")&&fUp.includes("DC")) { sfx="DCV"; eezUnit="volt";      rangeQuery="SENSe:VOLTage:DC:RANGe?"; nplcCmd="SENSe:VOLTage:DC:NPLCycles"; confCmd="CONFigure:VOLTage:DC DEF,DEF"; }
    else if (fUp.includes("VOLT")&&fUp.includes("AC")) { sfx="ACV"; eezUnit="volt";      rangeQuery="SENSe:VOLTage:AC:RANGe?"; nplcCmd=null; isAC=true; /* NPLCycles invalid for ACV on A.03.03 */ confCmd="CONFigure:VOLTage:AC DEF,DEF"; }
    else if (fUp.includes("CURR")&&fUp.includes("DC")) { sfx="DCI"; eezUnit="amp";       rangeQuery="SENSe:CURRent:DC:RANGe?"; nplcCmd="SENSe:CURRent:DC:NPLCycles"; confCmd="CONFigure:CURRent:DC DEF,DEF"; }
    else if (fUp.includes("CURR")&&fUp.includes("AC")) { sfx="ACI"; eezUnit="amp";       rangeQuery="SENSe:CURRent:AC:RANGe?"; nplcCmd=null; isAC=true; /* NPLCycles invalid for ACI on A.03.03 */ confCmd="CONFigure:CURRent:AC DEF,DEF"; }
    else if (fUp.includes("FRES"))                     { sfx="\u03a9 4W"; eezUnit="unknown"; rangeQuery="SENSe:FRESistance:RANGe?"; nplcCmd="SENSe:FRESistance:NPLCycles"; confCmd="CONFigure:FRESistance DEF,DEF"; }
    else if (fUp.includes("RES"))                      { sfx="\u03a9";    eezUnit="unknown"; rangeQuery="SENSe:RESistance:RANGe?";  nplcCmd="SENSe:RESistance:NPLCycles"; confCmd="CONFigure:RESistance DEF,DEF"; }
    else if (fUp.includes("FREQ"))                     { sfx="Hz";  eezUnit="frequency"; confCmd="CONFigure:FREQuency DEF,DEF"; }
    else if (fUp.includes("CAP"))                      { sfx="F";   eezUnit="unknown"; rangeQuery="SENSe:CAPacitance:RANGe?"; confCmd="CONFigure:CAPacitance DEF,DEF"; }
    else if (fUp.includes("TEMP"))                     { sfx="\u00b0C"; eezUnit="unknown"; confCmd="CONFigure:TEMPerature"; }
    else if (fUp.includes("CONT"))                     { sfx="\u03a9";  eezUnit="unknown"; confCmd="CONFigure:CONTinuity"; }
    else if (fUp.includes("DIOD"))                     { sfx="V";   eezUnit="volt"; confCmd="CONFigure:DIODe"; }
    else if (fUp.includes("PER"))                      { sfx="s";   eezUnit="unknown"; confCmd="CONFigure:PERiod DEF,DEF"; }

    const baseSfxMap = {"DCV":"V","ACV":"V","DCI":"A","ACI":"A"};
    const baseSfx = baseSfxMap[sfx] || sfx;

    // Query initial range BEFORE arming trigger
    if (rangeQuery) {
        const rr = parseFloat(qts(await connection.query(rangeQuery)));
        if (isFinite(rr) && rr > 0) conf.range = rr;
    }

    // Re-send CONFigure to initialise the measurement engine.
    // After *CLS or fresh connection, READ? hangs without this.
    if (confCmd) connection.command(confCmd);
    // AC bandwidth filter controls speed/accuracy for ACV/ACI (NPLC disabled for AC)
    if (isAC) connection.command("SENSe:VOLTage:AC:BANDwidth " + AC_BANDWIDTH);
    await new Promise(r=>setTimeout(r,200));

    let headerBase = buildHeader(conf.func, conf.range, conf.res, sfx);
    notify.update(toastId, {render: headerBase+"  \u2014 starting...", autoClose:false});

    // ── Configure instrument ───────────────────────────────────────────────
    // ABORt first, then configure, then arm.
    // Do NOT query anything between INITiate/*TRG and READ? — queries
    // interleaved with IMMediate trigger cause errors 113/230.
    // Instead: READ? itself triggers each reading; range check done AFTER
    // READ? returns (between readings), safely outside the trigger engine.
    connection.command("ABORt");
    if (nplcCmd) connection.command(nplcCmd + " " + NPLC);

    // ZERO:AUTO only valid for DCV, DCI, 2W/4W resistance
    const supportsZeroAuto = fUp.includes("VOLT:DC") || fUp.includes("CURR:DC")
        || fUp.includes("RES") || fUp.includes("FRES");
    if (supportsZeroAuto) connection.command("SENSe:ZERO:AUTO ONCE");

    // Minimal trigger setup — diagnostic confirmed:
    // TRIGger:SOURce IMMediate causes -113 on 34465A, so omitted.
    // TRIGger:COUNt INFinity causes READ? timeout, so omitted.
    // READ? self-triggers correctly with just SAMPle:COUNt 1.
    connection.command("SAMPle:COUNt 1");
    connection.command("FORMat:DATA ASCII");

    // ── Read loop ─────────────────────────────────────────────────────────
    var rmsVals=[], i=0;
    const unlimited = (COUNT===0);
    const SQRT2x2 = 2*Math.sqrt(2);

    while (unlimited || i<COUNT) {
        if (session.isStopped) {
            notify.update(toastId,{render:"34465A Live: stopped at "+i+" readings",autoClose:3000});
            break;
        }

        // READ? self-triggers — no separate INITiate/TRG needed
        const raw = parseFloat(qts(await connection.query("READ?")).trim());
        if (!isFinite(raw)) { i++; continue; }

        rmsVals.push(raw);
        const rmsMin = rmsVals.reduce((a,b)=>a<b?a:b, rmsVals[0]);
        const rmsMax = rmsVals.reduce((a,b)=>a>b?a:b, rmsVals[0]);
        let render;
        if (isAC) {
            const ppCur=raw*SQRT2x2, ppMin=rmsMin*SQRT2x2, ppMax=rmsMax*SQRT2x2;
            render = headerBase
                +"    "+row3("RMS",sfx,    rmsMin, raw,    rmsMax)
                +"    "+row3("P-P",baseSfx, ppMin,  ppCur,  ppMax);
        } else {
            render = headerBase+"    "+row3("",sfx,rmsMin,raw,rmsMax);
        }
        notify.update(toastId, {render, autoClose:false});

        // Range check AFTER READ? returns — safe, between readings
        // Any range step is a clean decade change, !== is the right test
        if (rangeQuery && i>0 && i%RANGE_CHECK_EVERY===0) {
            const newRange = parseFloat(qts(await connection.query(rangeQuery)));
            if (isFinite(newRange) && newRange>0 && newRange!==conf.range) {
                conf.range = newRange;
                const nc = parseConf(qts(await connection.query("CONFigure?")));
                conf.res = nc.res;
                headerBase = buildHeader(conf.func, conf.range, conf.res, sfx);
            }
        }
        i++;
    }

    if (rmsVals.length===0) throw new Error("No valid readings received");

    const min=rmsVals.reduce((a,b)=>a<b?a:b,rmsVals[0]);
    const max=rmsVals.reduce((a,b)=>a>b?a:b,rmsVals[0]);
    const mean=rmsVals.reduce((a,b)=>a+b,0)/rmsVals.length;
    const std=Math.sqrt(rmsVals.reduce((a,b)=>a+(b-mean)**2,0)/rmsVals.length);
    const pp=max-min;

    notify.dismiss(toastId);
    let summary=headerBase+"  N="+rmsVals.length
        +"    RMS: Mean="+fmtVal(mean,sfx)+"  \u03c3="+fmtVal(std,sfx)
        +"  Min="+fmtVal(min,sfx)+"  Max="+fmtVal(max,sfx);
    if (isAC) summary+="    P-P: Mean="+fmtVal(mean*SQRT2x2,baseSfx)
        +"  Min="+fmtVal(min*SQRT2x2,baseSfx)+"  Max="+fmtVal(max*SQRT2x2,baseSfx);
    notify.info(summary);

    const f64=new Float64Array(rmsVals), u8=new Uint8Array(f64.buffer);
    const vScale=(isFinite(conf.range)&&conf.range>0)
        ? conf.range/8
        : Math.max(pp>1e-9?pp/8:Math.abs(mean)/4, 1e-7);
    const estInterval=NPLC/60+0.05;  // NPLC/60Hz + ~50ms LAN overhead
    const hScale=(rmsVals.length*estInterval)/10;

    session.addChart({
        description:headerBase+" | N="+rmsVals.length+" | Mean="+fmtVal(mean,sfx)+" \u03c3="+fmtVal(std,sfx)+" PP="+fmtVal(pp,sfx),
        data:[u8], samplingRate:1/estInterval, offset:0, scale:1, format:8,
        unit:eezUnit, color:"#4CAF50", colorInverse:"#2E7D32", label:"34465A Live",
        viewOptions:{axesLines:{type:"fixed",majorSubdivision:{horizontal:10,vertical:8},minorSubdivision:{horizontal:5,vertical:5}}},
        horizontalScale:hScale, verticalScale:vScale
    });

} catch(e) {
    notify.update(toastId,{render:"Live Read failed: "+e.message,autoClose:5000,type:"error"});
} finally {
    connection.command("ABORt");
    connection.command("FORMat:DATA ASCII");
    connection.command("SYSTem:LOCal");  // return front panel control
    await new Promise(r=>setTimeout(r,200));
    connection.release();
}

function fmtVal(v, sfx) {
    if (!isFinite(v)) return String(v) + " " + sfx;
    const a = Math.abs(v), sg = v < 0 ? "-" : "";
    const noP = sfx.indexOf("\u00b0") >= 0 || sfx === "";
    if (noP || a === 0) return sg + parseFloat(a.toPrecision(6)) + " " + sfx;
    const P = [[1e12,"T"],[1e9,"G"],[1e6,"M"],[1e3,"k"],[1,""],[1e-3,"m"],[1e-6,"\u03bc"],[1e-9,"n"],[1e-12,"p"],[1e-15,"f"]];
