async function resetAndAcquire() {
    try { connection.release(); } catch(e) {}
    await new Promise(r=>setTimeout(r,500));
    await connection.acquire(true);
}

function qts(r) {
    if (r===null||r===undefined) return "";
    if (typeof r==="string") return r;
    if (typeof r==="number") return String(r);
    if (r.data) {
        const t=new TextDecoder().decode(new Uint8Array(r.data));
        return t.charAt(0)==='#'?t.substring(2+parseInt(t.charAt(1))):t;
    }
    return String(r);
}

async function step(label, fn) {
    try {
        const result = await fn();
        const e = qts(await connection.query("SYSTem:ERRor?")).trim();
        const ok = e.startsWith("+0") || e.startsWith("0,");
        notify.info((ok?"OK":"FAIL") + " " + label + (result?" => "+String(result).substring(0,25):"") + (ok?"":" ERR:"+e.substring(0,20)));
        return ok;
    } catch(ex) {
        notify.error("THROW " + label + ": " + (ex&&ex.message?ex.message:String(ex)));
        return false;
    }
}

notify.info("Diag v44: acquiring...");
await resetAndAcquire();
notify.info("Diag v44: ready");

try {
    await step("*CLS",          () => { connection.command("*CLS"); return null; });
    await step("ABORt",         () => { connection.command("ABORt"); return null; });

    // CONFigure? to read active function
    const conf = qts(await connection.query("CONFigure?")).trim().replace(/"/g,"");
    const e1 = qts(await connection.query("SYSTem:ERRor?")).trim();
    notify.info((e1.startsWith("+0")?"OK":"FAIL") + " CONFigure? => " + conf.substring(0,30));

    // Re-send CONFigure to ensure measurement engine is initialised
    const funcParts = conf.split(/[\s,]+/);
    const func = funcParts[0].toUpperCase();
    let confCmd = null;
    if      (func.includes("VOLT")&&func.includes("DC")) confCmd = "CONFigure:VOLTage:DC DEF,DEF";
    else if (func.includes("VOLT")&&func.includes("AC")) confCmd = "CONFigure:VOLTage:AC DEF,DEF";
    else if (func.includes("CURR")&&func.includes("DC")) confCmd = "CONFigure:CURRent:DC DEF,DEF";
    else if (func.includes("CURR")&&func.includes("AC")) confCmd = "CONFigure:CURRent:AC DEF,DEF";
    else if (func.includes("FRES"))                      confCmd = "CONFigure:FRESistance DEF,DEF";
    else if (func.includes("RES"))                       confCmd = "CONFigure:RESistance DEF,DEF";
    else if (func.includes("FREQ"))                      confCmd = "CONFigure:FREQuency DEF,DEF";
    else if (func.includes("CAP"))                       confCmd = "CONFigure:CAPacitance DEF,DEF";
    else if (func.includes("TEMP"))                      confCmd = "CONFigure:TEMPerature";
    else if (func.includes("CONT"))                      confCmd = "CONFigure:CONTinuity";
    else if (func.includes("DIOD"))                      confCmd = "CONFigure:DIODe";

    if (confCmd) {
        await step("CONFigure re-send: "+confCmd, () => { connection.command(confCmd); return null; });
    }

    // SENSe:VOLTage:AC:NPLCycles causes -113 on firmware A.03.03 — omitted
    await step("SAMPle:COUNt 1",() => { connection.command("SAMPle:COUNt 1"); return null; });

    // READ? should now work
    notify.info("Attempting READ?...");
    const val = qts(await connection.query("READ?")).trim();
    const e2 = qts(await connection.query("SYSTem:ERRor?")).trim();
    notify.info((e2.startsWith("+0")?"OK":"FAIL") + " READ? => " + val.substring(0,25) + " err:" + e2.substring(0,15));

    // Second READ? to confirm loop works
    const val2 = qts(await connection.query("READ?")).trim();
    notify.info("READ? #2 => " + val2.substring(0,25));

} catch(ex) {
    notify.error("Diag error: " + (ex&&ex.message?ex.message:String(ex)));
} finally {
    connection.command("ABORt");
    connection.command("SYSTem:LOCal");
    await new Promise(r=>setTimeout(r,200));
    connection.release();
    notify.info("Diag v44 done.");
}
